CREATE TABLE artists (id text PRIMARY KEY, name text NOT NULL, commission_rate numeric(5,2) NOT NULL DEFAULT 25);
CREATE TABLE categories (id text PRIMARY KEY, name text NOT NULL, slug text NOT NULL UNIQUE, description text, icon text, position_order integer NOT NULL DEFAULT 0);
CREATE TABLE collections (id text PRIMARY KEY, artist_id text NOT NULL REFERENCES artists(id), title text NOT NULL, slug text NOT NULL, banner_url text, description text, is_active boolean NOT NULL DEFAULT true, is_public boolean NOT NULL DEFAULT false, position_order integer NOT NULL DEFAULT 0, design_ids text[] NOT NULL DEFAULT '{}', UNIQUE(artist_id,slug));
CREATE TABLE artist_settings (artist_id text PRIMARY KEY REFERENCES artists(id), meta_pixel_id text, ga4_id text, tiktok_pixel_id text, custom_domain text);
CREATE TABLE products (id text PRIMARY KEY, name text NOT NULL, type text NOT NULL, description text, material text, fit text, category_id text REFERENCES categories(id), collection_id text REFERENCES collections(id), tags text[] NOT NULL DEFAULT '{}', base_price numeric(12,2) NOT NULL, base_cost numeric(12,2), artist_margin numeric(12,2) NOT NULL DEFAULT 0, platform_fee numeric(12,2) NOT NULL DEFAULT 0, final_price numeric(12,2), catalog_product boolean NOT NULL DEFAULT true, is_active boolean NOT NULL DEFAULT true, colors text[] NOT NULL DEFAULT '{}', sizes text[] NOT NULL DEFAULT '{}');
CREATE TABLE product_variants (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id), color text NOT NULL, size text NOT NULL, stock_quantity integer NOT NULL DEFAULT 0 CHECK (stock_quantity >= 0), is_active boolean NOT NULL DEFAULT true, debited_order_ids text[] NOT NULL DEFAULT '{}', released_order_ids text[] NOT NULL DEFAULT '{}', UNIQUE(product_id,color,size));
CREATE TABLE designs (id text PRIMARY KEY, artist_id text NOT NULL REFERENCES artists(id), title text NOT NULL, description text, image_url text NOT NULL, category text NOT NULL, category_id text REFERENCES categories(id), collection_id text REFERENCES collections(id), tags text[] NOT NULL DEFAULT '{}', base_cost numeric(12,2) NOT NULL DEFAULT 0, artist_margin numeric(12,2) NOT NULL DEFAULT 0, platform_fee numeric(12,2) NOT NULL DEFAULT 0, final_price numeric(12,2) NOT NULL DEFAULT 0, design_price numeric(12,2) NOT NULL DEFAULT 0, commission_rate numeric(5,2) NOT NULL DEFAULT 25, position_order integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'rascunho', production jsonb);
CREATE TABLE orders (id text PRIMARY KEY, order_number text UNIQUE, customer_email text NOT NULL, customer_name text, subtotal numeric(12,2) NOT NULL, shipping_cost numeric(12,2) NOT NULL DEFAULT 0, total numeric(12,2) NOT NULL, base_cost_total numeric(12,2) NOT NULL DEFAULT 0, artist_commission_total numeric(12,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending', payment_intent_id text UNIQUE, checkout_key text UNIQUE, checkout_token_hash text, shipping_address jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_items (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id text NOT NULL REFERENCES products(id), variant_id text NOT NULL REFERENCES product_variants(id), design_id text NOT NULL REFERENCES designs(id), artist_id text NOT NULL REFERENCES artists(id), quantity integer NOT NULL CHECK(quantity > 0), size text NOT NULL, color text NOT NULL, unit_price numeric(12,2) NOT NULL, base_cost numeric(12,2) NOT NULL, design_price numeric(12,2) NOT NULL, artist_commission numeric(12,2) NOT NULL, production jsonb);
CREATE INDEX idx_variants_product ON product_variants(product_id);
CREATE INDEX idx_categories_position ON categories(position_order);
CREATE INDEX idx_collections_artist_position ON collections(artist_id,position_order);
CREATE INDEX idx_designs_artist ON designs(artist_id);
CREATE INDEX idx_orders_payment ON orders(payment_intent_id);
CREATE INDEX idx_order_items_order ON order_items(order_id);